WITH matched_keys AS (SELECT account_type, status FROM accounts EXCEPT SELECT account_type, status FROM accounts WHERE status IN ('FROZEN', 'CLOSED', 'OPEN')), verified AS (SELECT s.* FROM accounts s INNER JOIN matched_keys k ON s.account_type = k.account_type AND s.status = k.status) SELECT account_type, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, COUNT(DISTINCT account_type) AS distinct_account_types, SUM(balance) FILTER (WHERE status = 'FROZEN') AS frozen_total_balance FROM verified GROUP BY account_type;
